#!/usr/bin/env bash
# sync-shells.sh
# Regenerates the thin per-tool command and agent files from the canonical ones:
#   .agents/workflows/<name>.md  ->  .claude/commands, .cursor/commands, .opencode/command, .gemini/commands
#   .agents/agents/<name>.md     ->  .claude/agents, .cursor/agents, .opencode/agents
# Antigravity reads .agents/ directly. Codex and other tools read AGENTS.md.
# Run it after adding or editing a workflow or an agent. Generated files say so in a
# comment; do not edit them by hand. Safe to run many times: the output is deterministic.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$root"

# fm <file> <key>: value of a key in the frontmatter
fm() {
  awk -v k="$2" '
    /^---[ \t]*$/ { n++; next }
    n == 1 && index($0, k ":") == 1 { sub("^" k ":[ \t]*", ""); print; exit }
  ' "$1"
}

# gen <path>: writes stdin to <path>
gen() {
  mkdir -p "$(dirname "$1")"
  cat > "$1"
  echo "  write   $1"
}

for wf in .agents/workflows/*.md; do
  n="$(basename "$wf" .md)"
  d="$(fm "$wf" description | tr -d '"')"

  gen ".claude/commands/$n.md" <<__EOF__
---
description: $d
---
<!-- generated by scripts/sync-shells.sh from .agents/workflows/$n.md -->
Follow \`.agents/workflows/$n.md\` exactly. Arguments: \$ARGUMENTS
__EOF__

  gen ".cursor/commands/$n.md" <<__EOF__
<!-- generated by scripts/sync-shells.sh from .agents/workflows/$n.md -->
Follow \`.agents/workflows/$n.md\` exactly. Use whatever the user typed after the command as the arguments.
__EOF__

  gen ".opencode/command/$n.md" <<__EOF__
---
description: $d
---
<!-- generated by scripts/sync-shells.sh from .agents/workflows/$n.md -->
Follow \`.agents/workflows/$n.md\` exactly. Arguments: \$ARGUMENTS
__EOF__

  gen ".gemini/commands/$n.toml" <<__EOF__
# generated by scripts/sync-shells.sh from .agents/workflows/$n.md
description = "$d"
prompt = """
Follow \`.agents/workflows/$n.md\` exactly. Arguments: {{args}}
"""
__EOF__
done

for ag in .agents/agents/*.md; do
  n="$(basename "$ag" .md)"
  d="$(fm "$ag" description | tr -d '"')"
  ro="$(fm "$ag" readonly)"

  {
    printf -- '---\nname: %s\ndescription: %s\n' "$n" "$d"
    if [ "$ro" = "true" ]; then printf 'tools: Read, Grep, Glob, Bash\n'; fi
    printf -- '---\n'
    printf '<!-- generated by scripts/sync-shells.sh from .agents/agents/%s.md -->\n' "$n"
    printf 'Follow `.agents/agents/%s.md`.\n' "$n"
    if [ "$ro" = "true" ]; then printf 'You are read-only: never edit files, never stage, commit or push.\n'; fi
  } | gen ".claude/agents/$n.md"

  {
    printf -- '---\nname: %s\ndescription: %s\n' "$n" "$d"
    if [ "$ro" = "true" ]; then printf 'readonly: true\n'; fi
    printf -- '---\n'
    printf '<!-- generated by scripts/sync-shells.sh from .agents/agents/%s.md -->\n' "$n"
    printf 'Follow `.agents/agents/%s.md`.\n' "$n"
    if [ "$ro" = "true" ]; then printf 'You are read-only: never edit files, never stage, commit or push.\n'; fi
  } | gen ".cursor/agents/$n.md"

  {
    printf -- '---\ndescription: %s\nmode: subagent\n' "$d"
    if [ "$ro" = "true" ]; then
      printf 'tools:\n  write: false\n  edit: false\n'
      printf 'permission:\n  bash:\n    "*": deny\n    "git diff*": allow\n    "git log*": allow\n    "git status*": allow\n    "git show*": allow\n'
    fi
    printf -- '---\n'
    printf '<!-- generated by scripts/sync-shells.sh from .agents/agents/%s.md -->\n' "$n"
    printf 'Follow `.agents/agents/%s.md`.\n' "$n"
  } | gen ".opencode/agents/$n.md"
done
